namespace ReadNest.Application.Abstractions;

/// <summary>
/// Private file storage for uploads (profile photos, reading files). Keys are generated by the store, never
/// taken from user input, and files are not reachable as static files: they are only served by endpoints that
/// check ownership or visibility first.
/// </summary>
public interface IFileStore
{
    /// <summary>
    /// Copies <paramref name="content"/> into a private temporary file while hashing it. Throws
    /// <see cref="FileTooLargeException"/> as soon as more than <paramref name="maxBytes"/> bytes arrive, so an
    /// oversized upload is never fully buffered. The staged file is deleted on dispose unless committed.
    /// </summary>
    Task<IStagedFile> StageAsync(Stream content, long maxBytes, CancellationToken cancellationToken);

    /// <summary>Stores a small, already validated file and returns its new key.</summary>
    Task<string> SaveAsync(string container, string extension, ReadOnlyMemory<byte> content, CancellationToken cancellationToken);

    /// <summary>Opens a stored file for reading, or returns null when the key is unknown or the file is missing.</summary>
    Stream? OpenRead(string key);

    /// <summary>Deletes a stored file. Missing files are ignored; failures are logged, not thrown.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}

/// <summary>An upload held in temporary storage until it has been validated.</summary>
public interface IStagedFile : IAsyncDisposable
{
    long Length { get; }

    /// <summary>Lower-case hex SHA-256 of the content.</summary>
    string Sha256 { get; }

    /// <summary>Opens the staged content for inspection (seekable, read-only).</summary>
    Stream OpenRead();

    /// <summary>Moves the staged file into permanent storage and returns its key.</summary>
    Task<string> CommitAsync(string container, string extension, CancellationToken cancellationToken);
}

public sealed class FileTooLargeException(long maxBytes) : Exception($"The file is larger than {maxBytes} bytes.")
{
    public long MaxBytes { get; } = maxBytes;
}

/// <summary>Size limits for uploads (configuration section "Uploads").</summary>
public sealed class UploadOptions
{
    public const string SectionName = "Uploads";

    public long ProfilePhotoMaxBytes { get; set; } = 5 * 1024 * 1024;

    public long ReadingFileMaxBytes { get; set; } = 50 * 1024 * 1024;

    public static string Describe(long bytes) =>
        bytes >= 1024 * 1024 ? $"{bytes / (1024d * 1024d):0.#} MB" : $"{Math.Max(1, bytes / 1024)} KB";
}

/// <summary>Validates, resizes and re-encodes uploaded images.</summary>
public interface IImageProcessor
{
    /// <summary>
    /// Decodes a JPEG, PNG or WebP image (checked by its signature, not its name or declared type), crops it to a
    /// square, scales it to at most <paramref name="size"/> pixels and re-encodes it as WebP without metadata.
    /// Throws <see cref="InvalidImageException"/> for anything else, including images too large to decode safely.
    /// </summary>
    byte[] NormalizeProfilePhoto(ReadOnlySpan<byte> content, int size);
}

public sealed class InvalidImageException(string message) : Exception(message);
